    "add_or_subtract_time": "Zeit addieren oder subtrahieren",
    "date_some_years_months": "Ein Datum einige Jahre, Monate und Tage später, unter 0 für früher: das Datum und sein Wochentag, sein Tag im Jahr und seine Kalenderwoche. Jahre und Monate zuerst; ein Monat nach dem 31. Januar ist der letzte Februar. Ein leeres Datum ist heute.",
