    "molar_mass_of_formula_2": "Die molare Masse einer Formel und der Anteil jedes Elements daran; Gramm, Mol und Teilchen; und die empirische und die Molekülformel einer Zusammensetzung.",
    "equation_balanced_with_kind": "Eine ausgeglichene Gleichung, mit ihrer Art und was sie oxidiert und reduziert; die Mengen einer Reaktion, ihr limitierender Reaktant und die prozentuale Ausbeute; ein Arbeitsblatt; Wärme, q = mcΔT; und Halbwertszeit.",
