    "unpaired_electrons": "Ungepaarte Elektronen",
    "electrons_alone_in_their": "Seine Elektronen, die allein in ihren Orbitalen sitzen, nach der Hundschen Regel: was ein Atom magnetisch macht.",
    "energy_to_warm_gram": "Die Energie, um ein Gramm davon um 1 K zu erwärmen, bei 25 °C: q = mcΔT. Für die meisten radioaktiven Elemente nicht gemessen.",
    "when_was_found_by": "Wann es gefunden wurde, von wem, und wer es zuerst rein herstellte.",
    "isotopes": "Isotope",
    "stable_isotopes_commonest_first": "Seine stabilen Isotope, das häufigste zuerst; ohne stabile die in der Natur vorkommenden, oder sein langlebigstes und seine Halbwertszeit.",
    "where_name_comes_from": "Woher sein Name kommt und wie es gefunden wurde.",
    "uses": "Verwendung",
    "what_used_for": "Wofür es verwendet wird.",
    "covalent_radius": "Kovalenzradius",
    "half_length_of_single": "Die halbe Länge einer Einfachbindung zwischen zwei seiner Atome, in Pikometern: wie groß sein Atom in einem Molekül ist, kleiner als sein Van-der-Waals-Radius.",
    "heat_of_fusion": "Schmelzwärme",
    "energy_to_melt_mole": "Die Energie, um ein Mol davon an seinem Schmelzpunkt zu schmelzen, ohne Temperaturänderung.",
    "heat_of_vaporization": "Verdampfungswärme",
    "energy_to_boil_mole": "Die Energie, um ein Mol davon an seinem Siedepunkt zu verdampfen, ohne Temperaturänderung.",
    "thermal_conductivity": "Wärmeleitfähigkeit",
    "how_well_heat_flows": "Wie gut Wärme hindurchfließt: Watt durch einen Meter davon je Kelvin zwischen seinen Enden, über einen Quadratmeter. Silber und Kupfer am meisten, die Gase am wenigsten.",
    "electrical_resistivity": "Spezifischer Widerstand",
    "how_much_resists_current": "Wie stark es einem Strom widersteht, bei 20 °C: R = ρL/A. Klein bei Metallen, Silbers 1.6 × 10⁻⁸ Ω·m am kleinsten; sehr groß bei einem Isolator wie Schwefel.",
    "mohs_hardness": "Mohshärte",
    "how_hard_by_what": "Wie hart es ist, daran gemessen, was es ritzt und was es ritzt, von Talks 1 bis Diamants 10.",
    "cas_number": "CAS-Nummer",
    "number_in_chemical_abstracts": "Seine Nummer im Register des Chemical Abstracts Service, das jeden Stoff einmal benennt: zum Nachschlagen überall.",
    "magnetism": "Magnetismus",
    "how_acts_in_magnetic": "Wie es sich in einem Magnetfeld verhält: ferromagnetisch, wie Eisen, selbst ein Magnet; paramagnetisch, schwach angezogen; diamagnetisch, schwach abgestoßen; antiferromagnetisch, der Magnetismus seiner Atome hebt sich auf.",
    "crystal_structure": "Kristallstruktur",
    "how_atoms_packed_in": "Wie seine Atome im Festkörper gepackt sind, bei Raumtemperatur. Darunter gezeichnet seine Elementarzelle, der kleinste sich wiederholende Kasten, oder bei einer hexagonalen ein Prisma aus 3; seine Atome nach ihrem Anteil gezählt: eines an einer Ecke gehört zu 8 Kästen oder 6 Prismen, eines auf einer Fläche zu 2. Graue Kugeln: nur ihr Gitter, mit vielen Atomen an jedem Punkt.",
    "abundance_in_crust": "Häufigkeit in der Erdkruste",
    "how_much_of_earth": "Welchen Anteil der Erdkruste es ausmacht, in mg/kg, Massenanteile pro Million: Sauerstoff knapp die Hälfte, dann Silicium. Nur Spuren: einige Atome zugleich, in Uran- und Thoriumerzen entstehend; synthetisch: nur im Labor erzeugt.",
    "appearance": "Aussehen",
    "what_looks_like_pure": "Wie es rein bei Raumtemperatur aussieht.",
    "light_of_atoms_as": "Das Licht seiner Atome als Gas, von violett bei 380 nm bis rot bei 750: Absorption, weißes Licht hindurchgeschickt, dunkle Linien im Regenbogen, wo es Farben herausnimmt; Emission, erhitzt oder im Funken, genau diese Farben allein, hell auf schwarz. Jedes Element hat eigene Linien, wie einen Fingerabdruck: so wurde Helium in der Sonne vor der Erde gefunden. Seine stärksten Linien, wie NIST sie listet, je stärker, desto breiter; bei einem Element, dessen Atom hier keine hat, die seines Ions. Klicken: das andere.",
    "alkali_metal": "Alkalimetall",
    "group_1_but_hydrogen": "Gruppe 1 außer Wasserstoff: weiche Metalle, die heftig mit Wasser reagieren und Hydroxide und Wasserstoff bilden. Ein Außenelektron, als 1+-Ion abgegeben.",
    "alkaline_earth_metal": "Erdalkalimetall",
    "group_2_reactive_metals": "Gruppe 2: reaktive Metalle, weniger als die Alkalimetalle. Zwei Außenelektronen, als 2+-Ion abgegeben.",
    "transition_metal": "Übergangsmetall",
    "groups_3_to_12": "Gruppen 3 bis 12, die d-Unterschalen füllend: harte Metalle mit vielen Oxidationsstufen und farbigen Verbindungen; gute Katalysatoren.",
    "post_transition_metal": "Metall nach den Übergangsmetallen",
    "metals_after_transition_metals": "Die Metalle nach den Übergangsmetallen: weicher, niedriger schmelzend, einige mit Oxiden, die sowohl sauer als auch basisch sind.",
    "metalloid": "Halbmetall",
    "between_metals_and_nonmetals": "Zwischen den Metallen und den Nichtmetallen: Halbleiter, wie Silicium und Germanium.",
    "nonmetal": "Nichtmetall",
    "poor_conductors_of_heat": "Schlechte Wärme- und Stromleiter, Gase oder spröde Festkörper, die in ihren Verbindungen Elektronen aufnehmen oder teilen.",
    "halogen": "Halogen",
    "group_17_reactive_nonmetals": "Gruppe 17: reaktive Nichtmetalle, ein Elektron von einer vollen Schale entfernt, als 1−-Ion aufgenommen; mit Metallen bilden sie Salze.",
    "noble_gas": "Edelgas",
    "group_18_their_shells": "Gruppe 18: ihre Schalen voll, sie reagieren kaum; Gase aus einzelnen Atomen.",
    "lanthanide": "Lanthanoid",
    "lanthanum_to_lutetium_filling": "Lanthan bis Lutetium, die 4f-Unterschale füllend: die Metalle der seltenen Erden, einander sehr ähnlich, meist 3+.",
    "actinide": "Actinoid",
    "actinium_to_lawrencium_filling": "Actinium bis Lawrencium, die 5f-Unterschale füllend: alle radioaktiv; nur Thorium und Uran kommen in der Natur häufig vor.",
    "draws_up_to_25": "Zeichnet bis zu 25 Funktionen von x, mit einem Regler für jeden anderen Buchstaben, wie a in a x^2 + b: x^2 – 3, 2sin(x); Folgen, a(n) = a(n – 1) + 2 {a(1) = 1}; und Richtungsfelder, dy/dx = x – y {y(0) = 1}, ein Klick fügt eine Lösung hinzu. Markiert Nullstellen, Maxima, Minima und Schnittpunkte. Ziehen zum Verschieben, scrollen oder zusammenziehen zum Zoomen; auf eine Kurve zeigen für ihre Werte, klicken für ihre Tangente. Der Reiter Tabelle listet sie auf.",
    "close_graph": "Den Graphen schließen",
    "functions_and_view_stay": "Die Funktionen und die Ansicht bleiben für das nächste Mal erhalten.",
    "clear_functions": "Die Funktionen löschen",
    "removes_every_curve_start": "Entfernt jede Kurve, Start und Schritt der Tabelle, und setzt die Ansicht zurück.",
    "zoom_in": "Vergrößern",
    "twice_as_close_about": "Doppelt so nah, um die Mitte. Das Rad zoomt um die Stelle, auf die es zeigt, und holt sie zur Mitte; eine Pinch-Geste zoomt um ihre Stelle.",
    "zoom_out": "Verkleinern",
    "twice_as_far_about": "Doppelt so weit, um die Mitte.",
    "back_to_start": "Zurück zum Anfang",
    "x_from_10_to": "x von -10 bis 10 mit 0 in der Mitte; bei einer Winkelfunktion in Deg eine ganze Umdrehung in beide Richtungen.",
    "graph_fills_page_to": "Der Graph füllt die Seite, um mehr von den Kurven zu sehen: auf der Website das ganze Fenster, in der Erweiterung ein eigenes Fenster neben dem Rechner.",
    "graph_small_again_over": "Der Graph ist wieder klein, über den Tasten.",
    "share_and_save": "Teilen und speichern",
    "copy_link_opens_graph": "Einen Link kopieren, der diesen Graphen mit seinen Kurven, Reglern, Ansicht und Einstellungen für jeden öffnet; ihn als Bild kopieren oder als PNG oder SVG speichern, mit der Funktion jeder Kurve; oder seine Tabelle als CSV speichern. Rechtsklick auf den Graphen für dasselbe.",
    "undo": "Rückgängig",
    "takes_back_last_change": "Nimmt die letzte Änderung des Graphen zurück: eine Eingabe, eine entfernte oder gelöschte Kurve, einen Regler, eine Einstellung, einen gezogenen Punkt. Nicht ein Verschieben oder Zoomen der Ansicht.",
    "redo": "Wiederherstellen",
