    "draws_straight_line_nearest": "Zeichnet die Gerade, die diesen Punkten am nächsten kommt, nach der Methode der kleinsten Quadrate; auf sie zeigen für ihr r². Erneut klicken für eine quadratische, exponentielle, Potenz- und logarithmische Anpassung.",
