    "fit_exponential": "Eine Exponentialfunktion anpassen",
    "draws_y_b_nearest": "Zeichnet stattdessen y = a · bˣ am nächsten an diesen Punkten, aus der Gerade von ln y, wie Rechner sie anpassen. Jedes y muss größer als 0 sein.",
    "fit_power": "Eine Potenzfunktion anpassen",
