    "hide_best_fit": "Die Ausgleichskurve ausblenden",
    "takes_curve_of_best": "Entfernt die Ausgleichskurve.",
    "points_as_table": "Punkte als Tabelle",
    "type_points_in_rows": "Die Punkte in Zeilen aus x und y eingeben; das Feld wird beim Tippen geschrieben, (1, 2), (2, 4.1). Enter geht in die Zeile darunter.",
    "put_table_away": "Die Tabelle wegräumen",
    "points_stay_in_box": "Die Punkte bleiben im Feld.",
    "draw_slope": "Die Steigung zeichnen",
    "draws_slope_of_curve": "Zeichnet auch die Steigung dieser Kurve, ihre Ableitung dy/dx, gestrichelt in ihrer Farbe.",
    "hide_slope": "Die Steigung ausblenden",
    "takes_dashed_curve_of": "Entfernt die gestrichelte Kurve der Steigung.",
    "hide_curve": "Die Kurve ausblenden",
    "hides_curve_and_points": "Blendet diese Kurve und ihre Punkte aus und lässt sie aus der Tabelle heraus. Die Eingabe bleibt. Das ▾ daneben, oder ein Rechtsklick, wählt ihre Farbe und ihre Linie, durchgezogen, gestrichelt oder gepunktet, dünn oder dick, und beschriftet Punkte.",
    "show_curve": "Die Kurve anzeigen",
    "draws_curve_again_beside": "Zeichnet diese Kurve wieder. Das ▾ daneben, oder ein Rechtsklick, wählt ihre Farbe und ihre Linie, durchgezogen, gestrichelt oder gepunktet, dünn oder dick, und beschriftet Punkte.",
    "color_and_line": "Farbe und Linie",
    "color_by_shade_hue": "Ihre Farbe, nach Helligkeit, Farbton oder Hex-Wert, Auto wieder ihre eigene; ihre Linie durchgezogen, gestrichelt oder gepunktet, dünn, normal oder dick; bei Punkten ihr x und y daneben; und Ausblenden oder Anzeigen.",
