    "puts_x_of_point": "Fügt das x dieses Punktes in die Gleichung ein, wie Ans. ← und → verschieben den Punkt entlang seiner Kurve, mit Shift weiter, ↑ und ↓ zur Kurve darüber oder darunter.",
