    "insert_slope": "Die Steigung einfügen",
    "puts_slope_of_curve": "Fügt die Steigung der Kurve an diesem Punkt, dy/dx, in die Gleichung ein, wie Ans. Die gestrichelte Linie ist ihre Tangente.",
    "graph_settings": "Graph-Einstellungen",
    "type_where_x_goes": "Eingeben, von wo bis wo x über den Graphen läuft und y nach oben, und mit welchem Schritt das Gitter geht, 0.5 oder π/2; darunter gleichen Maßstab, Gitter, Hilfslinien, ein Polargitter, jede Achse und ihre Zahlen und Pfeile ein- und ausschalten und die Ansicht festsetzen; und die Achsen benennen. Enter oder Esc geht zum Graphen zurück.",
    "same_scale": "Gleicher Maßstab",
    "unit_of_x_as": "Eine Einheit von x so lang wie eine von y, wie auch gezoomt wird: ein Kreis ist rund und eine Steigung von 1 bei 45°. Bei einer Winkelfunktion in Deg ein Radiant von x so lang wie 1 von y; in Rad das Gitter von x nach Zahlen und nicht nach π, damit seine Felder quadratisch sind.",
    "grid": "Gitter",
