    "lock_view": "Ansicht sperren",
    "dragging_wheel_and_pinch": "Ziehen, das Rad und eine Pinch-Geste verschieben die Ansicht nicht mehr, und die Zoom-Knöpfe verschwinden: um auf die Kurven zu zeigen und sie anzuklicken, ohne sie zu verschieben. Punkte und Flächen lassen sich weiter ziehen, und die Ansicht kann weiter eingegeben werden.",
    "area_under_curve": "Fläche unter einer Kurve",
    "press_then_drag_along": "Drücken, dann entlang einer Kurve von einem x zum anderen ziehen: die Fläche zwischen ihr und der x-Achse wird schattiert, über der Achse positiv und darunter negativ gezählt. Zwischen zwei Kurven gedrückt, die Fläche dazwischen, die obere minus die untere. Ein Ende nahe einer Nullstelle oder einem Schnittpunkt springt dorthin; am Rand gehalten, verschiebt sich die Ansicht für mehr. Es bleibt für eine weitere gedrückt, bis es erneut gedrückt wird, bei einem Doppelklick auf den Plot, Esc, oder einem Knopf der Ansicht.",
    "type_start": "Den Anfang eingeben",
    "type_x_area_starts": "Das x eingeben, bei dem die Fläche beginnt, eine beliebige Zahl unter ihrem Ende: die Fläche folgt beim Tippen. Enter oder Esc geht zum Graphen zurück.",
    "type_end": "Das Ende eingeben",
