    "statistics": "Statistik",
    "type_or_paste_list": "Eine Liste von Zahlen eingeben oder einfügen, auch eine Spalte aus einer Tabelle, für Mittelwert, Standardabweichung, Summe, Quartile, Median und mehr, mit Histogramm und Boxplot. Der Reiter Paare nimmt x und y in jeder Zeile, für die Ausgleichskurve und die Korrelation; der Reiter Tests prüft Hypothesen.",
