    "tests_of_hypotheses_as": "Hypothesentests, wie STAT TESTS eines TI-84: t und z für eine oder zwei Stichproben, gepaarter t-Test, Anteile, χ² als Anpassungs- und Unabhängigkeitstest, ANOVA und Korrelation, jeder mit seinem p-Wert und der Entscheidung über H₀.",
    "fit": "Anpassung",
    "curve_fitted_to_pairs": "Die an die Paare nach kleinsten Quadraten angepasste Kurve: eine Gerade, y = a + bx; quadratisch; kubisch; exponentiell, y = a · bˣ; Potenz, y = a · xᵇ; logarithmisch, y = a + b ln x; oder logistisch, y = c / (1 + a e^(–bx)). Exponentielle, Potenz- und logarithmische Anpassungen laufen über eine Gerade ihrer Logarithmen, wie Rechner sie anpassen.",
