    "every_tool_tabs_and": "Jedes Werkzeug: seine Reiter und Karten, die Formeln und Konstanten, die Beispiele des Graphen, die Elemente und die Einheiten, nach ihren Namen und ihren Hinweisen. Enter oder ein Klick öffnet das Gefundene.",
