    "draws_each_as_fraction": "Stellt beim Tippen jedes ÷ als Bruch dar und zeigt Ergebnisse als Brüche: 1 ÷ 2 + 1 ÷ 3 = 5/6. FRAC in der Anzeige zeigt, dass er an ist. Erneut klicken für Dezimalzahlen.",
    "degrees_minutes_seconds": "Grad, Minuten, Sekunden",
