    "reciprocal": "Kehrwert",
    "one_divided_by_number": "Eins geteilt durch die Zahl, nach ihr oder davor: 4 1/x = 0.25, und 1/x 4 = 0.25.",
    "square_root": "Quadratwurzel",
    "before_number_16_4": "Vor der Zahl: √ 16 = 4. Enter, → oder Tab schließt sie, als √(16); = rechnet sie aus.",
    "cube_root": "Kubikwurzel",
    "before_number_27_3": "Vor der Zahl: ∛ 27 = 3, wie 3 <sup>x</sup>√y 27; sie hebt x<sup>3</sup> auf. Negative Zahlen funktionieren: ∛ –8 = –2. Enter, → oder Tab schließt sie; = rechnet sie aus.",
