    "times_ten_to_power": "Mal zehn hoch die nächste Zahl: 5 EE 3 = 5000, 5 × 10<sup>3</sup>. Zuerst gedrückt, erscheint sie als zwei Felder zum Ausfüllen: Enter geht zum nächsten, die Pfeile und Tab wechseln zwischen ihnen, oder eines anklicken.",
